def badge_html(label: str, css_class: str) -> str:
    return f'<span class="fresh-pill {css_class}">{h(label)}</span>'



def industry_strength_label(industry_raw: str) -> tuple[str, str]:
    """Public stock-card badge: Industry Rank only.

    No Strong/Neutral/Weak wording is shown on the card. Styling still gives a
    subtle visual distinction for top-ranked and bottom-ranked industries.
    """
    key = industry_key(industry_raw)
    rank = INDUSTRY_POSITION_MAP.get(key)
    if rank:
        if INDUSTRY_RANK_MAP.get(key):
            return f"Industry Rank: {rank}", "support"
        if WEAK_INDUSTRY_POSITION_MAP.get(key):
            return f"Industry Rank: {rank}", "weak"
        return f"Industry Rank: {rank}", "rank"
    return "Industry Rank: -", "rank"

def render_stock_card(row: pd.Series, idx: int, daily_dir: Path, weekly_dir: Path, freshness_badges: list[tuple[str, str]] | None = None, streak: int | None = None, default_chart_mode: str = "Weekly", display_idx: int | None = None):
    ticker = str(row.get("ticker", "") or "").strip()
    key = safe_key(ticker or f"row_{idx}")
    display_num = int(display_idx if display_idx is not None else idx)
    mode_scope = "top_movers" if str(default_chart_mode).lower() == "daily" else "default"
    mode_key = f"chart_mode_{mode_scope}_{key}"
    if mode_key not in st.session_state:
        st.session_state[mode_key] = default_chart_mode

    liked = st.session_state.setdefault("liked_tickers", [])
    is_liked = ticker in liked

    stage = stock_stage_display_label(row)
    raw_stage = str(row.get("stage", stage) or stage).strip()
    stage_variant = str(row.get("stage_variant", "") or "").strip()
    stage_confidence = pd.to_numeric(row.get("stage_confidence"), errors="coerce")

    variant_line = ""

    industry_raw = str(row.get("Industry", row.get("industry", "-")) or "-")
    sector_raw = str(row.get("sector", row.get("Sector", "")) or "").strip()
    group_raw = str(row.get("industry_group", row.get("Industry Group", row.get("industry group", ""))) or "").strip()

    industry = f"{industry_icon(industry_raw)} {industry_raw}" if industry_raw and industry_raw != "-" else "-"
    strength_label, strength_style = industry_strength_label(industry_raw)
    name = stock_display_name(row)
    chart_mode = st.session_state.get(mode_key, default_chart_mode)
    chart_dir = daily_dir if chart_mode == "Daily" else weekly_dir
    suffix = "_daily.png" if chart_mode == "Daily" else "_weekly.png"
    chart = get_chart_bytes(chart_dir, ticker, suffix) if ticker else None

    # Desktop/laptop view shows both charts side by side.
    daily_chart = get_chart_bytes(daily_dir, ticker, "_daily.png") if ticker else None
    weekly_chart = get_chart_bytes(weekly_dir, ticker, "_weekly.png") if ticker else None

    badges = list(freshness_badges or [])
    if is_failed_stage2_value(stage) or is_failed_stage2_value(raw_stage):
        seen_date = str(row.get("failed_stage2_seen_date", "") or "").strip()
        badges.insert(0, (f"Failed Stage 2 · {seen_date}" if seen_date else "Failed Stage 2", "weak"))
    elif stage == "Not Sure":
        pending_raw = str(row.get("stage_pending_raw", "") or "").strip()
        if pending_raw:
            badges.insert(0, (f"Pending {pending_raw}", "rank"))
        else:
            badges.insert(0, ("Not Sure", "rank"))
    badges.append((strength_label, strength_style))
    industry_match_key = industry_key(industry_raw)
    industry_rank = INDUSTRY_POSITION_MAP.get(industry_match_key)
    top_position = INDUSTRY_RANK_MAP.get(industry_match_key)
    weak_position = WEAK_INDUSTRY_POSITION_MAP.get(industry_match_key)
    if industry_rank:
        badge_style = "support" if top_position else "weak" if weak_position else "rank"
    if streak and streak >= 2:
        badges.append((f"Seen in Interesting 20 for {streak} days", "repeat"))
    if is_liked:
        badges.insert(0, ("Liked", "support"))
    badge_line = "".join([badge_html(label, css_class) for label, css_class in badges])

    extra_meta = []

    extra_meta_line = ""
    if extra_meta:
        extra_meta_line = f"<div class=\"stock-meta\">{' · '.join(extra_meta)}</div>"

    # Use a real Streamlit container so the text, chart, and buttons are inside one card.
    with st.container(border=True):
        st.markdown(
            f"""
<div class="stock-card">
  <div class="stock-head">
    <div>
      <div class="stock-name"><span class="stock-number-badge">{display_num}</span><span class="stock-title-gold">{h(name)}</span> <span class="black-text">— {h(stage)}</span></div>
      <div class="stock-meta">Industry: {h(industry)}</div>
      {extra_meta_line}


  <div class="badge-strip">{badge_line}</div>
  <div class="signal-line">{h(volume_text(row, chart_mode))}</div>
  <div class="signal-line">{h(rs_text(row.get('rs_3m_pct'), '3m'))}</div>

""",
            unsafe_allow_html=True,
        )

        daily_img = chart_data_uri(daily_chart)
        weekly_img = chart_data_uri(weekly_chart)
        mobile_img = chart_data_uri(chart)

        # Desktop/laptop: show only side-by-side Daily + Weekly charts.
        if daily_img or weekly_img:
            daily_html = (
                f'<div class="desktop-chart-panel-v50"><div class="desktop-chart-title-v50">Daily Chart</div>'
                f'<img src="{daily_img}" alt="Daily chart for {h(name)}"></div>'
                if daily_img
                else '<div class="desktop-chart-panel-v50"><div class="desktop-chart-title-v50">Daily Chart</div><div class="chart-missing">Daily chart not available.</div></div>'
            )
            weekly_html = (
                f'<div class="desktop-chart-panel-v50"><div class="desktop-chart-title-v50">Weekly Chart</div>'
                f'<img src="{weekly_img}" alt="Weekly chart for {h(name)}"></div>'
                if weekly_img
                else '<div class="desktop-chart-panel-v50"><div class="desktop-chart-title-v50">Weekly Chart</div><div class="chart-missing">Weekly chart not available.</div></div>'
            )
            st.markdown(
                f'<div class="desktop-chart-duo-v50">{daily_html}{weekly_html}</div>',
                unsafe_allow_html=True,
            )

        # Mobile: earlier layout retained — one chart at a time, controlled by Daily/Weekly buttons.
        # This is pure HTML, not st.image(), so CSS can hide it on desktop reliably.
        if mobile_img:
            st.markdown(
                f'<div class="mobile-chart-single-v50"><div class="chart-wrap-v50"><img src="{mobile_img}" alt="{h(chart_mode)} chart for {h(name)}"></div></div>',
                unsafe_allow_html=True,
            )
        else:
            st.markdown(
                '<div class="mobile-chart-single-v50"><div class="chart-missing">Chart not available for this stock yet.</div></div>',
                unsafe_allow_html=True,
            )

        st.markdown('<div class="stock-actions-marker"></div>', unsafe_allow_html=True)
        c1, c2, c3 = st.columns(3)
        with c1:
            like_label = "♥ Liked" if is_liked else "♡ Like"
            if st.button(like_label, key=f"like_{key}_{idx}", use_container_width=True, type=("primary" if is_liked else "secondary")):
                liked = st.session_state.setdefault("liked_tickers", [])
                if ticker and ticker not in liked:
                    liked.append(ticker)
                rerun()
        with c2:
            daily_label = "Daily"
            if st.button(daily_label, key=f"daily_{key}_{idx}", use_container_width=True, type=("primary" if chart_mode == "Daily" else "secondary")):
                st.session_state[mode_key] = "Daily"
                rerun()
        with c3:
            weekly_label = "Weekly"
            if st.button(weekly_label, key=f"weekly_{key}_{idx}", use_container_width=True, type=("primary" if chart_mode == "Weekly" else "secondary")):
                st.session_state[mode_key] = "Weekly"
                rerun()

        if is_liked:
            st.markdown('<div class="liked-note">Saved to your liked list for this session.</div>', unsafe_allow_html=True)


