# Defensive helper guard: prevents NameError if this dashboard is merged with an older file
# where sort_stock_cards_alpha was accidentally removed or defined below usage.
if "sort_stock_cards_alpha" not in globals():
    def sort_stock_cards_alpha(df: pd.DataFrame) -> pd.DataFrame:
        if df is None or df.empty:
            return pd.DataFrame() if df is None else df
        out = normalize_columns(df).copy() if "normalize_columns" in globals() else df.copy()
        if "Company Name" in out.columns:
            key = out["Company Name"].fillna(out.get("ticker", "")).astype(str).str.lower()
        elif "ticker" in out.columns:
            key = out["ticker"].fillna("").astype(str).str.replace(".NS", "", regex=False).str.lower()
        else:
            return out.reset_index(drop=True)
        out["_alpha_sort_key"] = key
        return out.sort_values("_alpha_sort_key", ascending=True, na_position="last").drop(columns=["_alpha_sort_key"], errors="ignore").reset_index(drop=True)

